import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Renderer2, forwardRef } from '@angular/core';
import { BaseComponentWithTheme } from '../../utils';
import type { BreakpointCustomizable, PinCodeLength, PinCodeChangeEventDetail, PinCodeUpdateEventDetail, PinCodeState, Theme, PinCodeType } from '../types';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'p-pin-code,[p-pin-code]',
  template: '<ng-content />',
  inputs: ['compact', 'description', 'disabled', 'form', 'hideLabel', 'label', 'length', 'loading', 'message', 'name', 'required', 'state', 'theme', 'type', 'value'],
  outputs: ['blur', 'change', 'update'],
  standalone: false,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => PPinCode),
      multi: true,
    },
  ],
  host: {
    '(change)': '_onChange($event.target.value)',
    '(blur)': '_onTouched()'
  }
})
export class PPinCode extends BaseComponentWithTheme implements ControlValueAccessor {
  compact?: boolean;
  description?: string;
  disabled?: boolean;
  form?: string;
  hideLabel?: BreakpointCustomizable<boolean>;
  label?: string;
  length?: PinCodeLength;
  loading?: boolean;
  message?: string;
  name?: string;
  required?: boolean;
  state?: PinCodeState;
  declare theme?: Theme;
  type?: PinCodeType;
  value?: string;
  blur = new EventEmitter<CustomEvent<void>>();
  change = new EventEmitter<CustomEvent<PinCodeChangeEventDetail>>();
  /** @deprecated */
  update = new EventEmitter<CustomEvent<PinCodeUpdateEventDetail>>();
  constructor(
    private _renderer: Renderer2,
    private _elementRef: ElementRef,
    private _cdr: ChangeDetectorRef
  ) {
    super(_cdr, _elementRef);
  }

  _onChange: (value: any) => void = () => {};
  _onTouched: () => void = () => {};

  writeValue(value: any): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'value', value);
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'disabled', isDisabled);
  }
}