import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Renderer2, forwardRef } from '@angular/core';
import { BaseComponentWithTheme } from '../../utils';
import type { BreakpointCustomizable, TextareaBlurEventDetail, TextareaChangeEventDetail, TextareaInputEventDetail, TextareaResize, TextareaState, Theme, TextareaWrap } from '../types';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'p-textarea,[p-textarea]',
  template: '<ng-content />',
  inputs: ['autoComplete', 'compact', 'counter', 'description', 'disabled', 'form', 'hideLabel', 'label', 'maxLength', 'message', 'minLength', 'name', 'placeholder', 'readOnly', 'required', 'resize', 'rows', 'spellCheck', 'state', 'theme', 'value', 'wrap'],
  outputs: ['blur', 'change', 'input'],
  standalone: false,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => PTextarea),
      multi: true,
    },
  ],
  host: {
    '(input)': '_onChange($event.target.value)',
    '(blur)': '_onTouched()'
  }
})
export class PTextarea extends BaseComponentWithTheme implements ControlValueAccessor {
  autoComplete?: string;
  compact?: boolean;
  counter?: boolean;
  description?: string;
  disabled?: boolean;
  form?: string;
  hideLabel?: BreakpointCustomizable<boolean>;
  label?: string;
  maxLength?: number;
  message?: string;
  minLength?: number;
  name: string;
  placeholder?: string;
  readOnly?: boolean;
  required?: boolean;
  resize?: TextareaResize;
  rows?: number;
  spellCheck?: boolean;
  state?: TextareaState;
  declare theme?: Theme;
  value?: string;
  wrap?: TextareaWrap;
  blur = new EventEmitter<CustomEvent<TextareaBlurEventDetail>>();
  change = new EventEmitter<CustomEvent<TextareaChangeEventDetail>>();
  input = new EventEmitter<CustomEvent<TextareaInputEventDetail>>();
  constructor(
    private _renderer: Renderer2,
    private _elementRef: ElementRef,
    private _cdr: ChangeDetectorRef
  ) {
    super(_cdr, _elementRef);
  }

  _onChange: (value: any) => void = () => {};
  _onTouched: () => void = () => {};

  writeValue(value: any): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'value', value);
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'disabled', isDisabled);
  }
}