import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Renderer2, forwardRef } from '@angular/core';
import { BaseComponentWithTheme } from '../../utils';
import type { MultiSelectDropdownDirection, BreakpointCustomizable, MultiSelectChangeEventDetail, MultiSelectToggleEventDetail, MultiSelectUpdateEventDetail, MultiSelectState, Theme } from '../types';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'p-multi-select,[p-multi-select]',
  template: '<ng-content />',
  inputs: ['compact', 'description', 'disabled', 'dropdownDirection', 'form', 'hideLabel', 'label', 'message', 'name', 'required', 'state', 'theme', 'value'],
  outputs: ['blur', 'change', 'toggle', 'update'],
  standalone: false,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => PMultiSelect),
      multi: true,
    },
  ],
  host: {
    '(change)': '_onChange($event.target.value)',
    '(blur)': '_onTouched()'
  }
})
export class PMultiSelect extends BaseComponentWithTheme implements ControlValueAccessor {
  compact?: boolean;
  description?: string;
  disabled?: boolean;
  dropdownDirection?: MultiSelectDropdownDirection;
  form?: string;
  hideLabel?: BreakpointCustomizable<boolean>;
  label?: string;
  message?: string;
  name: string;
  required?: boolean;
  state?: MultiSelectState;
  declare theme?: Theme;
  value?: string[];
  blur = new EventEmitter<CustomEvent<void>>();
  change = new EventEmitter<CustomEvent<MultiSelectChangeEventDetail>>();
  toggle = new EventEmitter<CustomEvent<MultiSelectToggleEventDetail>>();
  /** @deprecated */
  update = new EventEmitter<CustomEvent<MultiSelectUpdateEventDetail>>();
  constructor(
    private _renderer: Renderer2,
    private _elementRef: ElementRef,
    private _cdr: ChangeDetectorRef
  ) {
    super(_cdr, _elementRef);
  }

  _onChange: (value: any) => void = () => {};
  _onTouched: () => void = () => {};

  writeValue(value: any): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'value', value);
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'disabled', isDisabled);
  }
}