import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Renderer2, forwardRef } from '@angular/core';
import { BaseComponentWithTheme } from '../../utils';
import type { BreakpointCustomizable, RadioGroupDirection, RadioGroupChangeEventDetail, RadioGroupState, Theme } from '../types';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'p-radio-group,[p-radio-group]',
  template: '<ng-content />',
  inputs: ['compact', 'description', 'direction', 'disabled', 'form', 'hideLabel', 'label', 'loading', 'message', 'name', 'required', 'state', 'theme', 'value'],
  outputs: ['blur', 'change'],
  standalone: false,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => PRadioGroup),
      multi: true,
    },
  ],
  host: {
    '(change)': '_onChange($event.target.value)',
    '(blur)': '_onTouched()'
  }
})
export class PRadioGroup extends BaseComponentWithTheme implements ControlValueAccessor {
  compact?: boolean;
  description?: string;
  direction?: BreakpointCustomizable<RadioGroupDirection>;
  disabled?: boolean;
  form?: string;
  hideLabel?: BreakpointCustomizable<boolean>;
  label?: string;
  loading?: boolean;
  message?: string;
  name: string;
  required?: boolean;
  state?: RadioGroupState;
  declare theme?: Theme;
  value?: string;
  blur = new EventEmitter<CustomEvent<void>>();
  change = new EventEmitter<CustomEvent<RadioGroupChangeEventDetail>>();
  constructor(
    private _renderer: Renderer2,
    private _elementRef: ElementRef,
    private _cdr: ChangeDetectorRef
  ) {
    super(_cdr, _elementRef);
  }

  _onChange: (value: any) => void = () => {};
  _onTouched: () => void = () => {};

  writeValue(value: any): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'value', value);
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'disabled', isDisabled);
  }
}