import { Component, EventEmitter } from '@angular/core';
import { BaseComponentWithTheme } from '../../utils';
import type { SelectedAriaAttributes, DrilldownAriaAttribute, DrilldownUpdateEventDetail, Theme } from '../types';

@Component({
  selector: 'p-drilldown,[p-drilldown]',
  template: '<ng-content />',
  inputs: ['activeIdentifier', 'aria', 'open', 'theme'],
  outputs: ['dismiss', 'update'],
  standalone: false
})
export class PDrilldown extends BaseComponentWithTheme {
  activeIdentifier?: string | undefined;
  aria?: SelectedAriaAttributes<DrilldownAriaAttribute>;
  open?: boolean;
  declare theme?: Theme;
  dismiss = new EventEmitter<CustomEvent<void>>();
  update = new EventEmitter<CustomEvent<DrilldownUpdateEventDetail>>();
  
}