import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Renderer2, forwardRef } from '@angular/core';
import { BaseComponentWithTheme } from '../../utils';
import type { BreakpointCustomizable, CheckboxBlurEventDetail, CheckboxChangeEventDetail, CheckboxUpdateEventDetail, CheckboxState, Theme } from '../types';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'p-checkbox,[p-checkbox]',
  template: '<ng-content />',
  inputs: ['checked', 'compact', 'disabled', 'form', 'hideLabel', 'indeterminate', 'label', 'loading', 'message', 'name', 'required', 'state', 'theme', 'value'],
  outputs: ['blur', 'change', 'update'],
  standalone: false,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => PCheckbox),
      multi: true,
    },
  ],
  host: {
    '(change)': '_onChange($event.target.checked)',
    '(blur)': '_onTouched()'
  }
})
export class PCheckbox extends BaseComponentWithTheme implements ControlValueAccessor {
  checked?: boolean;
  compact?: boolean;
  disabled?: boolean;
  form?: string;
  hideLabel?: BreakpointCustomizable<boolean>;
  indeterminate?: boolean;
  label?: string;
  loading?: boolean;
  message?: string;
  name?: string;
  required?: boolean;
  state?: CheckboxState;
  declare theme?: Theme;
  value?: string;
  blur = new EventEmitter<CustomEvent<CheckboxBlurEventDetail>>();
  change = new EventEmitter<CustomEvent<CheckboxChangeEventDetail>>();
  /** @deprecated */
  update = new EventEmitter<CustomEvent<CheckboxUpdateEventDetail>>();
  constructor(
    private _renderer: Renderer2,
    private _elementRef: ElementRef,
    private _cdr: ChangeDetectorRef
  ) {
    super(_cdr, _elementRef);
  }

  _onChange: (value: any) => void = () => {};
  _onTouched: () => void = () => {};

  writeValue(value: any): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'checked', value);
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'disabled', isDisabled);
  }
}