import { ChangeDetectorRef, Component, ElementRef, EventEmitter, Renderer2, forwardRef } from '@angular/core';
import { BaseComponentWithTheme } from '../../utils';
import type { SegmentedControlBackgroundColor, BreakpointCustomizable, SegmentedControlColumns, SegmentedControlChangeEventDetail, SegmentedControlUpdateEventDetail, SegmentedControlState, Theme } from '../types';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

@Component({
  selector: 'p-segmented-control,[p-segmented-control]',
  template: '<ng-content />',
  inputs: ['backgroundColor', 'columns', 'compact', 'description', 'disabled', 'form', 'hideLabel', 'label', 'message', 'name', 'noWrap', 'required', 'state', 'theme', 'value'],
  outputs: ['blur', 'change', 'segmentedControlChange', 'update'],
  standalone: false,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => PSegmentedControl),
      multi: true,
    },
  ],
  host: {
    '(change)': '_onChange($event.target.value)',
    '(blur)': '_onTouched()'
  }
})
export class PSegmentedControl extends BaseComponentWithTheme implements ControlValueAccessor {
  /** @deprecated */
  backgroundColor?: SegmentedControlBackgroundColor;
  columns?: BreakpointCustomizable<SegmentedControlColumns>;
  compact?: boolean;
  description?: string;
  disabled?: boolean;
  form?: string;
  hideLabel?: BreakpointCustomizable<boolean>;
  label?: string;
  message?: string;
  name?: string;
  noWrap?: boolean;
  required?: boolean;
  state?: SegmentedControlState;
  declare theme?: Theme;
  value?: string | number;
  blur = new EventEmitter<CustomEvent<void>>();
  change = new EventEmitter<CustomEvent<SegmentedControlChangeEventDetail>>();
  /** @deprecated */
  segmentedControlChange = new EventEmitter<CustomEvent<SegmentedControlUpdateEventDetail>>();
  /** @deprecated */
  update = new EventEmitter<CustomEvent<SegmentedControlUpdateEventDetail>>();
  constructor(
    private _renderer: Renderer2,
    private _elementRef: ElementRef,
    private _cdr: ChangeDetectorRef
  ) {
    super(_cdr, _elementRef);
  }

  _onChange: (value: any) => void = () => {};
  _onTouched: () => void = () => {};

  writeValue(value: any): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'value', value);
  }

  registerOnChange(fn: any): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._renderer.setProperty(this._elementRef.nativeElement, 'disabled', isDisabled);
  }
}